export function dependencies(graph: Record<string, string[]>, start: string): string[] {
  const visited = new Set<string>([start]);
  const pending = [start];
  while (pending.length > 0) {
    const id = pending.pop()!;
    const neighbors = Object.prototype.hasOwnProperty.call(graph, id) ? graph[id] : [];
    for (const dependency of neighbors ?? []) {
      if (visited.has(dependency)) continue;
      visited.add(dependency);
      pending.push(dependency);
    }
  }
  visited.delete(start);
  return [...visited].sort();
}

import test from "node:test";
import assert from "node:assert/strict";
import { dependencies } from "../src/graph.ts";
import { DocumentService } from "../src/service.ts";

test("transitive dependencies are unique and sorted through cycles and self-edges", () => {
  const graph = {
    root: ["z", "b", "root", "b"],
    z: ["c", "z"],
    b: ["c", "root"],
    c: ["a", "b"],
    unrelated: ["unreachable"],
  };
  const before = structuredClone(graph);
  for (const edges of Object.values(graph)) Object.freeze(edges);
  Object.freeze(graph);

  const expected = ["a", "b", "c", "z"];
  assert.deepEqual(dependencies(graph, "root"), expected);
  assert.deepEqual(new DocumentService().dependenciesFor(graph, "root"), expected);
  assert.deepEqual(graph, before);
});

test("missing graph entries are leaves, including inherited object names", () => {
  assert.deepEqual(dependencies({ root: ["missing", "toString"] }, "root"), ["missing", "toString"]);
  assert.deepEqual(dependencies({}, "missing"), []);
  assert.deepEqual(dependencies({}, "toString"), []);
  assert.deepEqual(dependencies({ root: [] }, "root"), []);
  assert.deepEqual(dependencies({ root: ["root"] }, "root"), []);
});

test("long dependency chains do not exhaust the call stack", () => {
  const graph = {};
  const expected = [];
  for (let i = 0; i < 20000; i++) {
    graph[String(i)] = [String(i + 1)];
    expected.push(String(i + 1));
  }
  assert.deepEqual(dependencies(graph, "0"), expected.sort());
});

